/**
 * Example saves for demos (content/examples, generated by content/examples/generate.mts).
 * Each loads on demand, so the examples never weigh on the first page load.
 */
import { applyEditOrThrow, parseDocument, type EditCommand, type EgressDocument, type PlaceableItem } from '@egress/core';

export interface ExampleSave {
  id: string;
  name: string;
  /** Size and layout in a few words. */
  note: string;
  /** A crowd that shows the layout's bottlenecks without waiting long. */
  people: number;
  load(): Promise<EgressDocument>;
}

const json = (load: () => Promise<{ default: unknown }>) => async () => parseDocument((await load()).default);

/** The original demo plan, with a glass and a reinforced wall to show the wall types. */
async function courtyard(): Promise<EgressDocument> {
  const doc = parseDocument((await import('../../content/scenes/two-rooms-corridor.json')).default);
  return furnishCourtyard({ ...doc, walls: doc.walls.map((w, i) => ({ ...w, material: i === 3 ? 'glass' : i === 7 ? 'reinforced' : 'normal' })) });
}

/**
 * Courtyard furniture: meeting tables in the west room, desks in the east room, and two ceiling
 * HVAC vents. The building has one exterior opening, so its airflow comes from the vents.
 */
export function furnishCourtyard(doc: EgressDocument): EgressDocument {
  const floorId = doc.floors[0].id;
  const put = (item: PlaceableItem, x: number, y: number, rotationDeg = 0): EditCommand => ({ kind: 'createPlaceable', floorId, item, position: { x, y }, rotationDeg });
  const commands: EditCommand[] = [
    ...[6.5, 9.8].flatMap(y => [put('table', 3, y), put('chair', 2.6, y - 0.75), put('chair', 3.4, y - 0.75), put('chair', 2.6, y + 0.75, 180), put('chair', 3.4, y + 0.75, 180)]),
    ...[11.8, 14.3].flatMap(x => [6.5, 9.5].flatMap(y => [put('desk', x, y), put('chair', x, y - 0.75)])),
    put('vent', 12, 4.2), put('vent', 4, 4.2),
  ];
  return { ...applyEditOrThrow(doc, { requestId: 'courtyard.furniture', commands }).doc, revision: doc.revision };
}

export const EXAMPLES: ExampleSave[] = [
  { id: 'courtyard', name: 'Courtyard Study', note: '16 × 12 m · two rooms on a corridor', people: 150, load: courtyard },
  { id: 'office', name: 'Office Floor', note: '24 × 16 m · offices, meeting room, open plan', people: 120, load: json(() => import('../../content/examples/office.json')) },
  { id: 'school', name: 'School Wing', note: '48 × 20 m · eleven classrooms off one corridor', people: 320, load: json(() => import('../../content/examples/school.json')) },
  { id: 'event-hall', name: 'Event Hall', note: '36 × 24 m · foyer, hall and backstage', people: 500, load: json(() => import('../../content/examples/event-hall.json')) },
  { id: 'clinic', name: 'Two-Story Clinic', note: '20 × 15 m · two floors joined by a stair', people: 80, load: json(() => import('../../content/examples/clinic.json')) },
];
